python -c "import yaml,json; d=yaml.safe_load(open(r'C:\Users\carys\.cursor\skills\nd-code-analyzer\references\nd-patterns.yaml',encoding='utf-8')); print(type(d), len(d) if isinstance(d,list) else list(d.keys())[:20]); 
patterns=d if isinstance(d,list) else d.get('patterns',d.get('nd_patterns',[]));
print('count',len(patterns));
print(json.dumps({k:patterns[0].get(k) for k in patterns[0] if k!='false_positive_hints_md'}, indent=2)[:2000] if patterns else 'none')"

$rg = "c:\Users\carys\AppData\Local\Programs\cursor\resources\app\node_modules\@vscode\ripgrep\bin\rg.exe"
$yaml = Get-Content "C:\Users\carys\.cursor\skills\nd-code-analyzer\references\nd-patterns.yaml" -Raw
$root = "C:\Users\carys\cts"
$outDir = "C:\Users\carys\cts\.cursor\nd-scan"
New-Item -ItemType Directory -Force -Path $outDir | Out-Null

# Parse patterns: split on "- id:"
$blocks = [regex]::Split($yaml, '(?m)^  - id: ') | Select-Object -Skip 1
$patterns = @()
foreach ($b in $blocks) {
  if ($b -notmatch '^"([^"]+)"') { continue }
  $id = $Matches[1]
  $name = if ($b -match '(?m)^    name: "([^"]+)"') { $Matches[1] } else { $id }
  $sev = if ($b -match '(?m)^    severity_default: (\w+)') { $Matches[1] } else { 'LOW' }
  $cat = if ($b -match '(?m)^    category: (\w+)') { $Matches[1] } else { '' }
  $tier = if ($b -match '(?m)^    tier: (\d+)') { [int]$Matches[1] } else { 1 }
  if ($sev -notin @('HIGH','MEDIUM')) { continue }
  $regexes = @()
  if ($b -match '(?ms)^    regex:\r?\n((?:      - .+\r?\n)+)') {
    $rxBlock = $Matches[1]
    foreach ($line in ($rxBlock -split "`n")) {
      if ($line -match "^\s+- '(.+)'\s*(?:#.*)?$") { $regexes += $Matches[1] }
      elseif ($line -match '^\s+- "(.+)"\s*(?:#.*)?$') { $regexes += $Matches[1] }
    }
  }
  if ($regexes.Count -eq 0) { continue }
  $patterns += [pscustomobject]@{ id=$id; name=$name; severity=$sev; category=$cat; tier=$tier; regexes=$regexes }
}

Write-Host "Patterns to scan: $($patterns.Count)"
$candidates = @()
$g = @('--glob','*.cc','--glob','*.cpp','--glob','*.cxx','--glob','*.C','--glob','*.h','--glob','*.hh','--glob','*.hpp')
foreach ($p in $patterns) {
  $seen = @{}
  foreach ($rx in $p.regexes) {
    $args = @('-n','--no-heading','-U','--pcre2') + $g + @($rx, $root)
    try {
      $hits = & $rg @args 2>$null
    } catch { $hits = @() }
    if (-not $hits) { continue }
    foreach ($line in $hits) {
      if ($line -match '^(.+?):(\d+):(.*)$') {
        $file = $Matches[1]
        $lnum = [int]$Matches[2]
        $text = $Matches[3]
        # skip test dirs lightly? keep all for triage
        $key = "$($p.id)|$file|$lnum"
        if ($seen.ContainsKey($key)) { continue }
        $seen[$key] = $true
        $rel = $file.Substring($root.Length).TrimStart('\','/')
        $candidates += [pscustomobject]@{
          pattern_id = $p.id
          pattern_name = $p.name
          category = $p.category
          tier = $p.tier
          severity_default = $p.severity
          file = $rel.Replace('\','/')
          line = $lnum
          match_text = $text.Trim()
        }
      }
    }
  }
  Write-Host ("  {0} {1}: {2} hits" -f $p.id, $p.severity, $seen.Count)
}

$json = @{
  module_path = $root
  module_slug = 'cts'
  search_backend = 'rg'
  patterns_evaluated = $patterns.Count
  min_severity = 'MEDIUM'
  candidate_count = $candidates.Count
  candidates = $candidates
} | ConvertTo-Json -Depth 6 -Compress:$false
# ConvertTo-Json may mess up nesting; write via .NET for reliability
Add-Type -AssemblyName System.Web.Extensions -ErrorAction SilentlyContinue
$serializer = New-Object System.Web.Script.Serialization.JavaScriptSerializer
$serializer.MaxJsonLength = [int]::MaxValue
# Build hashtable carefully
$obj = @{
  module_path = $root
  module_slug = 'cts'
  search_backend = 'rg'
  patterns_evaluated = $patterns.Count
  min_severity = 'MEDIUM'
  candidate_count = $candidates.Count
  candidates = @($candidates | ForEach-Object {
    @{
      pattern_id = $_.pattern_id
      pattern_name = $_.pattern_name
      category = $_.category
      tier = $_.tier
      severity_default = $_.severity_default
      file = $_.file
      line = $_.line
      match_text = $_.match_text
    }
  })
}
$outPath = Join-Path $outDir 'candidates.json'
[System.IO.File]::WriteAllText($outPath, ($obj | ConvertTo-Json -Depth 8))
Write-Host "Wrote $outPath count=$($candidates.Count)"
# Summary by pattern
$candidates | Group-Object pattern_id | Sort-Object Count -Descending | ForEach-Object { Write-Host ("SUMMARY {0}: {1}" -f $_.Name, $_.Count) }
# Unique files
Write-Host ("Unique files: {0}" -f (($candidates | Select-Object -ExpandProperty file -Unique).Count))

$rg = "c:\Users\carys\AppData\Local\Programs\cursor\resources\app\node_modules\@vscode\ripgrep\bin\rg.exe"
$root = "C:\Users\carys\cts"
# Multi-line aware: find std::sort(...begin...end...) with NO third arg - use rg -U
# Better approach: for each 1.1 hit, read +/- 3 lines and classify
$j = Get-Content "C:\Users\carys\cts\.cursor\nd-scan\candidates.json" -Raw | ConvertFrom-Json
$hits = $j.candidates | Where-Object { $_.pattern_id -eq '1.1' -and $_.file -notmatch '(^|/)(test|python|docs)/' }
$noCmp = @(); $hasCmp = @(); $valueType = @(); $unknown = @()
foreach ($h in $hits) {
  $fp = Join-Path $root ($h.file -replace '/','\')
  if (-not (Test-Path $fp)) { continue }
  $lines = Get-Content $fp
  $i = $h.line - 1
  if ($i -lt 0 -or $i -ge $lines.Count) { continue }
  # gather window from sort line until ; or 8 lines
  $chunk = ''
  for ($k=0; $k -lt 8 -and ($i+$k) -lt $lines.Count; $k++) {
    $chunk += $lines[$i+$k] + "`n"
    if ($lines[$i+$k] -match ';') { break }
  }
  if ($chunk -match 'sort\s*\([^;]*,[^;]*,') { $hasCmp += $h; continue }
  # two-arg sort
  $prev = if ($i -gt 0) { ($lines[([Math]::Max(0,$i-5))..$i] -join "`n") } else { '' }
  $elemHint = $prev + $chunk
  if ($elemHint -match 'vector\s*<\s*(int|float|double|size_t|unsigned|long|std::string)') { $valueType += $h; continue }
  $noCmp += [pscustomobject]@{ file=$h.file; line=$h.line; chunk=($chunk -replace '\s+',' ').Trim().Substring(0,[Math]::Min(180,(($chunk -replace '\s+',' ').Trim().Length))) }
}
Write-Host "1.1 hasCmp=$($hasCmp.Count) noCmp=$($noCmp.Count) valueTypeHint=$($valueType.Count)"
$noCmp | Select -First 40 | ForEach-Object { Write-Host ("{0}:{1} :: {2}" -f $_.file,$_.line,$_.chunk) }
$noCmp | ConvertTo-Json | Set-Content "C:\Users\carys\cts\.cursor\nd-scan\prio_1.1_nocmp.json"
Write-Host "wrote nocmp count=$($noCmp.Count)"

$rg = "c:\Users\carys\AppData\Local\Programs\cursor\resources\app\node_modules\@vscode\ripgrep\bin\rg.exe"
$root = "C:\Users\carys\cts"
$j = Get-Content "C:\Users\carys\cts\.cursor\nd-scan\candidates.json" -Raw | ConvertFrom-Json

# 1.2: pointer set/map - check if same line or next few chars have comparator after *
$hits12 = $j.candidates | Where-Object { $_.pattern_id -eq '1.2' -and $_.file -notmatch '(^|/)(test|python|docs)/' }
$suspect12 = @(); $safeCmp = @(); $uniquePtr = @()
foreach ($h in $hits12) {
  $t = $h.match_text
  if ($t -match 'unique_ptr|shared_ptr|weak_ptr') { $uniquePtr += $h; continue }
  # If template already has 3rd arg on same line after *
  if ($t -match '(?:set|map|multiset|multimap)\s*<[^>]*\*\s*,[^>]+,[^>]+>') { $safeCmp += $h; continue }
  if ($t -match '(?:set|map)\s*<[^>]*\*\s*,\s*[^,>]+>') { $safeCmp += $h; continue } # set with cmp
  # Read declaration window
  $fp = Join-Path $root ($h.file -replace '/','\')
  if (-not (Test-Path $fp)) { continue }
  $lines = Get-Content $fp
  $i = $h.line - 1
  $chunk = ($lines[[Math]::Max(0,$i)..[Math]::Min($lines.Count-1,$i+3)] -join ' ')
  if ($chunk -match 'ndmObjPtrCmp|compareObjPtr|dosContainer::keyCompare|PtrCmp|IdCmp|StableCmp|less_|\w+Cmp\s*>') { $safeCmp += $h; continue }
  if ($chunk -match '(?:set|map|multiset|multimap)\s*<[^;{]*>') {
    $decl = $Matches[0]
    # count commas at template top-ish - crude: if has comparator after pointer
    if ($decl -match '\*\s*,') { $safeCmp += $h; continue }
  }
  $suspect12 += [pscustomobject]@{file=$h.file;line=$h.line;text=($t.Substring(0,[Math]::Min(120,$t.Length)))}
}
Write-Host "1.2 total=$($hits12.Count) safeCmp~=$($safeCmp.Count) uniquePtr=$($uniquePtr.Count) suspect=$($suspect12.Count)"
$suspect12 | Group-Object file | Sort Count -Desc | Select -First 20 | ForEach-Object { Write-Host ("F {0}: {1}" -f $_.Name, $_.Count) }
$suspect12 | Select -First 50 | ForEach-Object { Write-Host ("{0}:{1} {2}" -f $_.file,$_.line,$_.text) }
$suspect12 | ConvertTo-Json | Set-Content "C:\Users\carys\cts\.cursor\nd-scan\prio_1.2_suspect.json"

# 1.3 pointer unordered - similar
$hits13 = $j.candidates | Where-Object { $_.pattern_id -eq '1.3' -and $_.file -notmatch '(^|/)(test|python|docs)/' }
$suspect13 = @(); $safe13 = @()
foreach ($h in $hits13) {
  $t = $h.match_text
  $fp = Join-Path $root ($h.file -replace '/','\')
  if (-not (Test-Path $fp)) { continue }
  $lines = Get-Content $fp
  $i = $h.line - 1
  $chunk = ($lines[[Math]::Max(0,$i)..[Math]::Min($lines.Count-1,$i+4)] -join ' ')
  if ($chunk -match 'ptrHash|PtrHash|IdHash|keyHash|ndmPtrMapHash|compareObjPtr|StablePtr') { $safe13 += $h; continue }
  if ($chunk -match 'unordered_(?:set|map)\s*<[^;{]*,[^;{]*,') { $safe13 += $h; continue } # custom hash present
  $suspect13 += [pscustomobject]@{file=$h.file;line=$h.line;text=($t.Substring(0,[Math]::Min(120,$t.Length)))}
}
Write-Host "1.3 total=$($hits13.Count) safe~=$($safe13.Count) suspect=$($suspect13.Count)"
$suspect13 | Select -First 40 | ForEach-Object { Write-Host ("{0}:{1} {2}" -f $_.file,$_.line,$_.text) }
$suspect13 | ConvertTo-Json | Set-Content "C:\Users\carys\cts\.cursor\nd-scan\prio_1.3_suspect.json"
Write-Host "unique 1.3 files: $(($suspect13|Select -Expand file -Unique).Count)"
